import * as THREE from 'three/webgpu';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Load texture
  const texture = ctx.textureLoader.load(config.imageUrl);
  texture.colorSpace = THREE.SRGBColorSpace;

  // Create plane geometry (aspect ratio 512/320 = 1.6)
  const geometry = new THREE.PlaneGeometry(1.6, 1);

  // Create material
  const material = new THREE.MeshBasicMaterial({
    map: texture,
  });

  // Create mesh
  const mesh = new THREE.Mesh(geometry, material);

  // Apply scene position from config
  if (config.scenePosition) {
    const { x = 0, y = 0, z = 0, rotationXYZ, scaleXYZ } = config.scenePosition;
    mesh.position.set(x, y, z);

    if (rotationXYZ) {
      mesh.rotation.order = 'XYZ';
      mesh.rotation.x = rotationXYZ[0];
      mesh.rotation.y = rotationXYZ[1];
      mesh.rotation.z = rotationXYZ[2];
    }

    if (scaleXYZ) {
      mesh.scale.set(scaleXYZ[0], scaleXYZ[1], scaleXYZ[2]);
    }
  }

  group.add(mesh);

  // Event handlers (required structure)
  group.userData.handlers = {};

  // Cleanup function
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    texture.dispose();
  };

  return group;
}
